{
  "name": "pg_usage",
  "description": "What uses a Postgres table/view/function, or what an object/service uses, across database objects AND code: services (passports: reads, writes, entity, repository, migration owner, SQL calls, with file:line), functions/procedures (bodies), triggers, views, foreign keys. direction=used_by (default) answers \"who touches X\"; direction=uses answers \"what does X touch\" (X can be a function, view or service name). Returns a preview plus `view`, a link to the full result as an interactive table (shown to the user inline). Mention the link.",
  "group": "pg",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "name": {
        "type": "string",
        "description": "schema.table, schema.function, plain name, db:schema.name, or a service (direction=uses)"
      },
      "env": {
        "type": "string",
        "enum": [
          "dev",
          "fixture"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "direction": {
        "type": "string",
        "enum": [
          "used_by",
          "uses"
        ],
        "default": "used_by"
      }
    },
    "required": [
      "name"
    ]
  }
}
